
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from '@playwright/test';

/**
 * Connect Playwright to an already-running Chrome instance.
 * Reads the DevToolsActivePort file generated by Chrome.
 */
export async function connectToExistingChrome() {
    const debugFile = path.join(
        process.env.LOCALAPPDATA,
        'Google',
        'Chrome',
        'User Data',
        'DevToolsActivePort'
    );

    if (!fs.existsSync(debugFile)) {
        throw new Error(
            `Chrome debugging file not found: ${debugFile}. ` +
            'Check that Chrome is running with remote debugging enabled.'
        );
    }

    const [port, wsPath] = fs.readFileSync(debugFile, 'utf8')
        .trim()
        .split(/\r?\n/);

    if (!port || !wsPath?.startsWith('/devtools/browser/')) {
        throw new Error(
            'Invalid DevToolsActivePort file. Restart Chrome with debugging enabled.'
        );
    }

    const cdpUrl = `ws://127.0.0.1:${port}${wsPath}`;

    const browser = await chromium.connectOverCDP(cdpUrl, {
        timeout: 10_000,
    });

    const context = browser.contexts()[0];

    if (!context) {
        throw new Error('No existing Chrome browser context was found.');
    }

    const page = await context.newPage();

    return { browser, context, page };
}
